const GLOSSARY={
 'management by exception':['Management by exception','Routine work stays with your departments until service, cash, capacity, safety, trust, or uncertainty crosses an escalation threshold.'],
 'challenge lane':['Challenge the lane','A commercial action: spend effort and cash to win business in a corridor where a rival is strong. It is not a physical reroute.'],
 'partner access':['Partner-accessible capacity','Capacity a carrier says it can make available to you. It is not yours until you contract it; availability and price can change.'],
 'lease':['Lease','Longer-term access to equipment you do not own. It creates recurring monthly cost and usually a smaller upfront payment than buying.'],
 'staffing agency':['Staffing agency','A recruiter sources a candidate for a placement fee. In this game the standard agency fee is 20% of first-year salary, paid before the person starts.']
};

function readGame(){try{return clone(window.__atlasGameState||JSON.parse(localStorage.getItem(GAME_KEY)||'{}'))}catch{return{}}}
function normalizeFleet(asset){if(asset.category&&asset.accessModel&&asset.units)return asset;const lower=String(asset.kind||'').toLowerCase(),capacity=String(asset.capacity||''),category=lower.includes('air')?'Air':lower.includes('vessel')||lower.includes('ocean')?'Ocean':lower.includes('trailer')?'Trailer':'Truck',accessModel=lower.startsWith('owned')?'Owned':lower.includes('leased')?'Leased':'Contracted',match=capacity.match(/(\d+)/);return{...asset,category,accessModel,units:Number(match?.[1]||1),unitLabel:category==='Ocean'?'FEU':category==='Air'?'pallets':category==='Trailer'?'trailer':'tractor',monthlyCost:Number(asset.monthlyCost||0)}}
function mergeManagement(raw={}){const base=clone(DEFAULT_MANAGEMENT),next={...base,...raw};next.departments={...base.departments,...(raw.departments||{})};for(const key of Object.keys(base.departments))next.departments[key]={...base.departments[key],...(raw.departments?.[key]||{})};next.fleet=(Array.isArray(raw.fleet)?raw.fleet:base.fleet).map(normalizeFleet);next.carriers=Array.isArray(raw.carriers)?raw.carriers.map((c,i)=>({...base.carriers[i%base.carriers.length],...c,access:{...base.carriers[i%base.carriers.length].access,...(c.access||{})}})):base.carriers;next.drivers=Array.isArray(raw.drivers)?raw.drivers.map(d=>({...d,annualCost:Number(d.annualCost||DRIVER_ANNUAL_COST)})):base.drivers;next.candidates=Array.isArray(raw.candidates)?raw.candidates.map((c,i)=>({...base.candidates[i%base.candidates.length],...c,salary:Number(c.salary||base.candidates[i%base.candidates.length].salary)})):base.candidates;for(const key of['staffingPipeline','capacityPipeline','activeGlobal','completedGlobal','feed'])if(!Array.isArray(next[key]))next[key]=clone(base[key]);return next}

let management=mergeManagement(readGame().management),dialog=null,reviewDialog=null,activeTab='departments',worldMap=null,mainOverlay=null,syncing=false,refreshTimer=null,reviewAction=null;
function gameHour(){return Number(readGame().totalHours||8)}
function departmentAnnualPayroll(){return Object.entries(management.departments).reduce((sum,[key,d])=>sum+Number(d.headcount||0)*STAFFING[key].salary,0)}
function driverAnnualPayroll(){return management.drivers.reduce((sum,d)=>sum+Number(d.annualCost||DRIVER_ANNUAL_COST),0)}
function annualPayroll(){return departmentAnnualPayroll()+driverAnnualPayroll()}
function monthlyAssetCommitments(){return management.fleet.reduce((sum,a)=>sum+Number(a.monthlyCost||0),0)}
function pendingDepartment(key){return management.staffingPipeline.filter(x=>x.kind==='department'&&x.department===key).length}
function payrollCard(){const game=readGame();return`<div class="management-budget-strip"><div><span>Cash available</span><strong>${money(game.cash)}</strong></div><div><span>Annual people budget</span><strong>${money(annualPayroll())}</strong></div><div><span>Monthly people payroll</span><strong>${money(annualPayroll()/12)}</strong></div><div><span>Monthly asset commitments</span><strong>${money(monthlyAssetCommitments())}</strong></div><div><span>Pending requisitions</span><strong>${management.staffingPipeline.length+management.capacityPipeline.length}</strong></div></div>`}
function toast(text){let node=$('#management-toast');if(!node){node=document.createElement('div');node.id='management-toast';node.className='management-toast';document.body.append(node)}node.textContent=text;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),2400)}
function log(text){management.feed.unshift({at:gameHour(),text});management.feed=management.feed.slice(0,40)}
function persist(patch={},message='Management plan updated.'){const game=readGame(),next={...game,...patch,management:clone(management)};localStorage.setItem(GAME_KEY,JSON.stringify(next));window.__atlasGameState=clone(next);syncing=true;window.dispatchEvent(new CustomEvent('atlas-game-loaded',{detail:next}));syncing=false;window.dispatchEvent(new CustomEvent('atlas-game-changed',{detail:next}));if(message)toast(message)}
function cashAfter(upfront){return Number(readGame().cash||0)-Number(upfront||0)}
function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{renderDeck();wireEntryPoints();decorateGlossary();if(dialog&&!dialog.hidden)renderModal();renderMainMapOverlay()},70)}

function settlePipelines(){const now=gameHour();let changed=false;const readyStaff=management.staffingPipeline.filter(x=>now>=x.readyAt);for(const req of readyStaff){if(req.kind==='department'){management.departments[req.department].headcount+=1;log(`${req.title} started in ${management.departments[req.department].name}.`)}if(req.kind==='driver'){management.drivers.push({id:uid('DRV'),name:req.name,region:req.region,reliability:req.reliability,hours:10,status:'Available',morale:84,annualCost:req.salary});management.candidates=management.candidates.filter(x=>x.id!==req.candidateId);log(`${req.name} completed onboarding and joined the driver pool.`)}changed=true}if(readyStaff.length)management.staffingPipeline=management.staffingPipeline.filter(x=>now<x.readyAt);const readyCapacity=management.capacityPipeline.filter(x=>now>=x.readyAt);for(const req of readyCapacity){management.fleet.push({...req.asset,id:uid('CAP'),status:'Available',condition:100});log(`${req.label} became available to operations.`);changed=true}if(readyCapacity.length)management.capacityPipeline=management.capacityPipeline.filter(x=>now<x.readyAt);const last=Number(management.lastCostAt??now),elapsed=Math.max(0,now-last);if(elapsed>0){const labor=annualPayroll()/8760*elapsed,assets=monthlyAssetCommitments()/730*elapsed,total=Math.round(labor+assets);management.lastCostAt=now;if(total>0){const game=readGame();persist({cash:Math.max(0,Number(game.cash||0)-total)},`Operating payroll and lease costs: ${money(total)}.`);return}}if(changed)persist({},'Pending management commitments became available.')}

function ensureReview(){if(reviewDialog)return;document.body.insertAdjacentHTML('beforeend',`<div id="management-review" class="management-review" hidden><div role="dialog" aria-modal="true" aria-labelledby="management-review-title"><button type="button" class="review-close" aria-label="Close">×</button><p class="eyebrow">REVIEW COMMITMENT</p><h2 id="management-review-title"></h2><p class="review-summary"></p><div class="review-lines"></div><div class="review-warning"></div><div class="review-actions"><button type="button" class="review-confirm">Confirm</button><button type="button" class="review-cancel">Cancel</button></div></div></div>`);reviewDialog=$('#management-review');const cancel=()=>{reviewDialog.hidden=true;reviewAction=null};reviewDialog.querySelector('.review-close').onclick=cancel;reviewDialog.querySelector('.review-cancel').onclick=cancel;reviewDialog.onclick=e=>{if(e.target===reviewDialog)cancel()};reviewDialog.querySelector('.review-confirm').onclick=()=>{const fn=reviewAction;reviewDialog.hidden=true;reviewAction=null;fn?.()}}
function review({title,summary,rows=[],warning='',confirmLabel='Confirm',onConfirm}){ensureReview();reviewDialog.querySelector('#management-review-title').textContent=title;reviewDialog.querySelector('.review-summary').textContent=summary;reviewDialog.querySelector('.review-lines').innerHTML=rows.map(([label,value,kind=''])=>`<div class="${kind}"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('');reviewDialog.querySelector('.review-warning').textContent=warning;reviewDialog.querySelector('.review-confirm').textContent=confirmLabel;reviewAction=onConfirm;reviewDialog.hidden=false;reviewDialog.querySelector('.review-confirm').focus()}
function financialRows(upfront,annualRecurring=0,monthlyRecurring=0,leadHours=0){const cash=Number(readGame().cash||0),rows=[['Current cash',money(cash)],['Upfront commitment',money(upfront),'cost'],['Cash after confirmation',money(cash-upfront),cash-upfront<0?'bad':'']];if(annualRecurring)rows.push(['Annual people cost after start',money(annualRecurring)]);if(monthlyRecurring)rows.push(['Monthly recurring asset cost',money(monthlyRecurring)]);if(leadHours)rows.push(['Expected availability',`${Math.round(leadHours/24)} game days · H+${Math.round(gameHour()+leadHours)}`]);return rows}

function globalBounds(){return window.L?.latLngBounds(HUBS.map(item=>[item.lat,item.lng]))}
function fitGlobal(){const map=window.__atlasMainGameMap;if(!map||!window.L)return;map.setMinZoom(2);map.fitBounds(globalBounds(),{padding:[28,28],maxZoom:2})}
function renderMainMapOverlay(){const map=window.__atlasMainGameMap;if(!map||!window.L)return;if(mainOverlay){mainOverlay.remove();mainOverlay=null}mainOverlay=window.L.layerGroup().addTo(map);for(const item of HUBS)window.L.circleMarker([item.lat,item.lng],{radius:4,weight:1,opacity:.5,fillOpacity:.25}).addTo(mainOverlay).bindTooltip(`${item.name} · ${item.country}`).on('click',()=>openControl('world'))}
function globalizeMainMap(){const map=window.__atlasMainGameMap;if(!map)return;renderMainMapOverlay();fitGlobal();const fit=$('#fit-map'),show=$('#show-all');if(fit){fit.textContent='Fit global network';fit.onclick=fitGlobal}if(show){show.textContent='Open global control tower';show.onclick=()=>openControl('world')}if(!$('#focus-active-chapter')&&fit){const button=document.createElement('button');button.id='focus-active-chapter';button.className='secondary';button.type='button';button.textContent='Focus active chapter';button.onclick=()=>map.setView([38.2,-96.4],4);fit.insertAdjacentElement('afterend',button)}}

function queueFor(key){const game=readGame();if(key==='dispatch')return`${(game.orders||[]).filter(x=>x.status==='ready').length} ready loads`;if(key==='production')return`${(game.orders||[]).filter(x=>x.status==='production').length} production jobs`;if(key==='updates')return`${(game.exceptions||[]).length} escalations`;return`${Number(window.__atlasRoutineGlobalMoveCount||0)+management.activeGlobal.length} international moves`}
function departmentCards(){return Object.entries(management.departments).map(([key,d])=>{const staff=STAFFING[key],pending=pendingDepartment(key);return`<article class="management-card department-card"><header><div><span class="management-kicker">${esc(queueFor(key))}</span><h3>${esc(d.name)}</h3><p>${esc(d.lead)}</p></div><label class="switch"><input type="checkbox" data-dept="${key}" ${d.enabled?'checked':''}><span></span></label></header><p>${esc(d.description)}</p><div class="management-stat-grid"><div><strong>${d.headcount}</strong><span>active people</span></div><div><strong>${pending}</strong><span>agency pipeline</span></div><div><strong>${money(d.headcount*staff.salary)}</strong><span>annual payroll</span></div><div><strong>${money(staff.salary)}</strong><span>next hire salary</span></div></div><div class="management-mini"><span>${esc(d.policy)}</span><span>Agency fee ${pct(AGENCY_RATE)}</span><span>${Math.round(staff.leadHours/24)}d hiring lead</span></div><div class="management-row"><button type="button" data-request-hire="${key}">Request 1 hire</button><button type="button" data-reduce="${key}" ${d.headcount<=1?'disabled':''}>Reduce 1 position</button><select data-policy="${key}" aria-label="${esc(d.name)} policy"><option>Lean</option><option>Balanced</option><option>Service first</option><option>Quality first</option><option>Proactive</option><option>Manual review</option></select></div></article>`}).join('')}
function capacityTotals(category){const assets=management.fleet.filter(a=>a.category===category&&a.status!=='Maintenance'),sum=model=>assets.filter(a=>a.accessModel===model).reduce((s,a)=>s+Number(a.units||1),0),partner=management.carriers.reduce((s,c)=>s+Number(c.access?.[category]||0),0);return{owned:sum('Owned'),leased:sum('Leased'),contracted:sum('Contracted'),partner,onHand:sum('Owned')+sum('Leased')+sum('Contracted')}}
function capacitySummary(){const configs=[['Truck','trucks'],['Trailer','trailers'],['Ocean','FEU'],['Air','pallets']];return`<div class="capacity-matrix">${configs.map(([category,label])=>{const t=capacityTotals(category);return`<article><h4>${esc(category)}</h4><div><span>Owned</span><strong>${t.owned}</strong></div><div><span>Leased</span><strong>${t.leased}</strong></div><div><span>Contracted/on hand</span><strong>${t.contracted}</strong></div><div><span>Partner accessible</span><strong>${t.partner}</strong></div><footer><span>Immediately controlled</span><strong>${t.onHand} ${label}</strong></footer></article>`}).join('')}</div>`}
function fleetCards(){return management.fleet.map(a=>`<article class="asset-row"><div><span class="access-pill ${String(a.accessModel).toLowerCase()}">${esc(a.accessModel)}</span><strong>${esc(a.name)}</strong><small>${esc(a.kind)} · ${esc(a.base)} · ${esc(a.capacity)}</small></div><div class="asset-health"><span>${esc(a.status)}</span>${a.condition<100?`<meter min="0" max="100" value="${a.condition}"></meter>`:''}</div><div><small>${Number(a.monthlyCost||0)?`${money(a.monthlyCost)}/mo`:'No recurring fixed fee'}</small><button type="button" data-maintain="${a.id}">${a.status==='Maintenance'?'Return to service':'Inspect / maintain'}</button></div></article>`).join('')}
function procurementCards(){return CAPACITY_CATALOG.map(item=>`<article class="management-card procurement-card"><header><div><span class="management-kicker">${esc(item.accessModel)} · ${esc(item.category)}</span><h3>${esc(item.label)}</h3></div><strong>${money(item.upfront)}</strong></header><div class="management-mini"><span>${item.units} ${esc(item.unitLabel)}</span><span>${item.monthly?`${money(item.monthly)}/mo`:'no fixed monthly'}</span><span>${Math.round(item.leadHours/24)}d lead</span></div><button type="button" data-procure="${item.id}">Review commitment</button></article>`).join('')}
function pendingCapacityCards(){if(!management.capacityPipeline.length)return'<p class="management-note">No capacity currently on order.</p>';return management.capacityPipeline.map(x=>`<article class="candidate-row"><div><strong>${esc(x.label)}</strong><small>${esc(x.asset.accessModel)} · ${esc(x.asset.category)} · ${x.asset.units} ${esc(x.asset.unitLabel)}</small></div><span>Available H+${Math.round(x.readyAt)}</span></article>`).join('')}
function carrierCards(){return management.carriers.map(c=>`<article class="management-card carrier-card"><header><div><span class="management-kicker">${esc(c.mode)}</span><h3>${esc(c.name)}</h3><p>${esc(c.markets)}</p></div><strong>${c.reputation}/100</strong></header><div class="relationship"><span>Relationship ${c.relationship}</span><i style="width:${c.relationship}%"></i></div><div class="management-mini"><span>${esc(c.capacity)}</span><span>${esc(c.contact)}</span></div><div class="partner-access">${Object.entries(c.access||{}).map(([mode,count])=>`<span><b>${count}</b> ${esc(mode)} accessible</span>`).join('')}</div><div class="management-row"><button type="button" data-call="${c.id}">Call carrier</button><button type="button" class="primary" data-contract="${c.id}">Review capacity contract</button></div></article>`).join('')}
function peopleCards(){const pendingDrivers=management.staffingPipeline.filter(x=>x.kind==='driver'),drivers=management.drivers.map(d=>`<article class="management-card driver-card"><header><div><span class="management-kicker">${esc(d.region)}</span><h3>${esc(d.name)}</h3></div><strong>${d.reliability}%</strong></header><div class="management-mini"><span>${d.hours}h available</span><span>${esc(d.status)}</span><span>${money(d.annualCost)}/yr loaded cost</span></div><button type="button" data-offer="${d.id}" ${d.status!=='Available'?'disabled':''}>Review priority load offer</button></article>`).join(''),candidates=management.candidates.map(c=>{const fee=Math.round(c.salary*AGENCY_RATE);return`<article class="candidate-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.region)} · reliability ${c.reliability}% · ${money(c.salary)}/yr · agency fee ${money(fee)}</small></div><button type="button" data-hire-driver="${c.id}">Review hire</button></article>`}).join(''),pending=pendingDrivers.map(x=>`<article class="candidate-row"><div><strong>${esc(x.name)}</strong><small>Agency placement accepted · ${money(x.salary)}/yr</small></div><span>Starts H+${Math.round(x.readyAt)}</span></article>`).join('');return`${payrollCard()}<div class="management-intro"><h3>Drivers and dispatchable people</h3><p>Drivers are recurring labor commitments, not free capacity. Offers are reviewed before dispatch.</p></div><div class="management-grid">${drivers}</div><section class="management-group"><div class="group-title"><h3>Staffing-agency candidate slate</h3><span>20% placement fee</span></div>${candidates||'<p>No open candidates.</p>'}</section><section class="management-group"><div class="group-title"><h3>Pending driver starts</h3><span>${pendingDrivers.length}</span></div>${pending||'<p>No drivers onboarding.</p>'}</section>`}
function carrierOptions(op){const mode=op.mode.toLowerCase();return management.carriers.filter(c=>c.mode.toLowerCase().includes(mode)||c.mode.includes('+')).map(c=>`<option value="${c.id}">${esc(c.name)} · rep ${c.reputation}</option>`).join('')}
function opportunityCards(limit=8){const active=new Set(management.activeGlobal.map(x=>x.id));return OPPORTUNITIES.slice(0,limit).map(op=>`<article class="global-opportunity ${active.has(op.id)?'active':''}"><div><span class="management-kicker">${op.mode} · ${op.risk} risk</span><h3>${op.id} · ${esc(hub(op.from).name)} → ${esc(hub(op.to).name)}</h3><p>${esc(op.customer)} · ${esc(op.cargo)} · ${esc(op.service)}</p><div class="management-mini"><span>${money(op.value)} revenue</span><span>${money(op.buy)} buy</span><span>${money(op.value-op.buy)} gross spread</span><span>${op.hours} game hours</span></div></div>${active.has(op.id)?'<b>IN TRANSIT</b>':`<div class="opportunity-actions"><select data-carrier-for="${op.id}">${carrierOptions(op)}</select><button class="primary" data-book="${op.id}">Review lane booking</button></div>`}</article>`).join('')}
function glossaryCards(){return Object.entries(GLOSSARY).map(([term,[title,copy]])=>`<article><h3>${esc(title)}</h3><p>${esc(copy)}</p><span>${esc(term)}</span></article>`).join('')}
function deckMarkup(){const people=Object.values(management.departments).reduce((s,d)=>s+d.headcount,0)+management.drivers.length,truck=capacityTotals('Truck'),ocean=capacityTotals('Ocean'),air=capacityTotals('Air');return`<section id="global-3pl-deck" class="global-3pl-deck"><div class="deck-heading"><div><p class="eyebrow">GLOBAL 3PL CONTROL TOWER</p><h2>Manage commitments before they become costs.</h2></div><button class="primary" data-open-control="departments">Manage company</button></div><div class="global-scorecards"><button data-open-control="departments"><strong>${people}</strong><span>active people · ${management.staffingPipeline.length} pending</span></button><button data-open-control="fleet"><strong>${truck.onHand} / ${truck.partner}</strong><span>truck on hand / partner</span></button><button data-open-control="fleet"><strong>${ocean.onHand} / ${ocean.partner}</strong><span>FEU on hand / partner</span></button><button data-open-control="fleet"><strong>${air.onHand} / ${air.partner}</strong><span>air pallets / partner</span></button><button data-open-control="departments"><strong>${money(annualPayroll()/12)}</strong><span>monthly people payroll</span></button></div><p class="global-role-copy">Owned and leased assets are controlled inventory. Contracted blocks are committed capacity. Partner-accessible capacity is only potential until you review and confirm a purchase.</p></section>`}
function renderDeck(){let deck=$('#global-3pl-deck'),ops=$('.operations-deck');if(!ops)return;const holder=document.createElement('div');holder.innerHTML=deckMarkup();if(deck)deck.replaceWith(holder.firstElementChild);else ops.insertAdjacentElement('afterbegin',holder.firstElementChild);$('#global-3pl-deck')?.querySelectorAll('[data-open-control]').forEach(b=>b.onclick=()=>openControl(b.dataset.openControl))}

function modalMarkup(){return`<div id="management-modal" class="management-modal" hidden><div class="management-shell" role="dialog" aria-modal="true"><header><div><p class="eyebrow">GLOBAL 3PL CONTROL TOWER</p><h2>Run the company, not just the load</h2><p>Review cost, timing, capacity, and budget impact before making a commitment.</p></div><button class="management-close" aria-label="Close">×</button></header><nav class="management-tabs"><button data-tab="departments">Departments</button><button data-tab="fleet">Fleet & capacity</button><button data-tab="carriers">Carrier network</button><button data-tab="people">People & HR</button><button data-tab="world">World network</button><button data-tab="glossary">Game terms</button></nav><div id="management-content" class="management-content"></div><aside class="management-activity"><h3>Control-tower log</h3><div id="management-feed"></div></aside></div></div>`}
function ensureModal(){if($('#management-modal')){dialog=$('#management-modal');return}document.body.insertAdjacentHTML('beforeend',modalMarkup());dialog=$('#management-modal');dialog.querySelector('.management-close').onclick=closeControl;dialog.onclick=e=>{if(e.target===dialog)closeControl()};dialog.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderModal()})}
function openControl(tab='departments'){ensureModal();activeTab=tab;dialog.hidden=false;document.body.classList.add('management-open');renderModal();dialog.querySelector('.management-close')?.focus()}
function closeControl(){if(!dialog)return;dialog.hidden=true;document.body.classList.remove('management-open');worldMap?.remove();worldMap=null}
function renderModal(){if(!dialog)return;dialog.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));const content=$('#management-content');if(activeTab==='departments')content.innerHTML=`${payrollCard()}<div class="management-intro"><h3>Routine departments</h3><p>Headcount is active staff only. New people enter through a staffing-agency requisition, carry a 20% first-year salary placement fee, and do not count until their lead time finishes.</p></div><div class="management-grid">${departmentCards()}</div>`;if(activeTab==='fleet')content.innerHTML=`${payrollCard()}<div class="management-intro"><h3>Fleet and capacity inventory</h3><p>Owned, leased, contracted, and partner-accessible capacity are intentionally separate. Only the first three are immediately under your control.</p></div>${capacitySummary()}<section class="management-group"><div class="group-title"><h3>Controlled capacity</h3><span>${management.fleet.length} records</span></div>${fleetCards()}</section><section class="management-group"><div class="group-title"><h3>Capacity procurement</h3><span>Review before committing</span></div><div class="management-grid">${procurementCards()}</div></section><section class="management-group"><div class="group-title"><h3>Pending capacity</h3><span>${management.capacityPipeline.length}</span></div>${pendingCapacityCards()}</section>`;if(activeTab==='carriers')content.innerHTML=`${payrollCard()}<div class="management-intro"><h3>Carrier relationship book</h3><p>Partner-accessible capacity is visibility, not inventory. Review a contract before capacity becomes committed and cash leaves the business.</p></div><div class="management-grid">${carrierCards()}</div>`;if(activeTab==='people')content.innerHTML=peopleCards();if(activeTab==='world')content.innerHTML=`${payrollCard()}<div class="world-summary"><div><strong>${HUBS.length}</strong><span>global hubs</span></div><div><strong>${management.carriers.length}</strong><span>carrier partners</span></div><div><strong>${Number(window.__atlasRoutineGlobalMoveCount||0)+management.activeGlobal.length}</strong><span>international moves</span></div><div><strong>${management.completedGlobal.length}</strong><span>completed lanes</span></div></div><div id="management-world-map" class="management-world-map"></div><p class="management-note">Routine supply chains are already moving globally. New commercial lanes require an explicit financial review.</p><div class="global-opportunity-list">${opportunityCards()}</div>`;if(activeTab==='glossary')content.innerHTML=`<div class="glossary-list">${glossaryCards()}</div>`;$('#management-feed').innerHTML=(management.feed||[]).slice(0,14).map(x=>`<div class="management-event"><b>H+${x.at}</b><span>${esc(x.text)}</span></div>`).join('')||'<p>No management activity yet.</p>';wireModal();if(activeTab==='world')requestAnimationFrame(renderWorldMap)}
function renderWorldMap(){const host=$('#management-world-map');if(!host||!window.L)return;worldMap?.remove();worldMap=window.L.map(host,{zoomControl:true,minZoom:2,worldCopyJump:true}).fitBounds(globalBounds(),{padding:[20,20]});window.L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(worldMap);for(const item of HUBS)window.L.circleMarker([item.lat,item.lng],{radius:6,weight:2,fillOpacity:.82}).addTo(worldMap).bindPopup(`<b>${esc(item.name)}</b><br>${esc(item.country)}`);setTimeout(()=>worldMap?.invalidateSize(),40)}

function requestDepartmentHire(key){const d=management.departments[key],s=STAFFING[key],fee=Math.round(s.salary*AGENCY_RATE),upfront=fee+s.onboarding;if(cashAfter(upfront)<0)return toast('Not enough cash for the agency fee and onboarding.');review({title:`Open requisition · ${d.name}`,summary:`Atlas Talent Partners will source one ${s.title}. The person does not join headcount until the hiring lead time finishes.`,rows:[...financialRows(upfront,annualPayroll()+s.salary,0,s.leadHours),['Base salary',money(s.salary)],['Agency placement fee',`${money(fee)} · 20% of first-year salary`],['Onboarding / equipment',money(s.onboarding)],['Department now',`${d.headcount} active · ${pendingDepartment(key)} pending`],['Department after start',`${d.headcount+1} active`]],warning:'The placement fee is paid now. Salary begins when the person starts.',confirmLabel:'Approve requisition',onConfirm:()=>{management.staffingPipeline.push({id:uid('REQ'),kind:'department',department:key,title:s.title,salary:s.salary,upfront,agencyFee:fee,createdAt:gameHour(),readyAt:gameHour()+s.leadHours});log(`Staffing agency requisition opened for ${d.name}; ${money(upfront)} committed.`);persist({cash:cashAfter(upfront)},'Staffing requisition opened.');renderModal()}})}
function reduceDepartment(key){const d=management.departments[key],s=STAFFING[key];if(d.headcount<=1)return;const severance=Math.round(s.salary/13);review({title:`Reduce one position · ${d.name}`,summary:'This removes one active position immediately and pays roughly four weeks of severance.',rows:[['Current headcount',String(d.headcount)],['Headcount after',String(d.headcount-1)],['Severance',money(severance)],['Annual payroll after',money(annualPayroll()-s.salary)],['Cash after',money(cashAfter(severance))]],warning:'Lower headcount can increase routine queue pressure.',confirmLabel:'Confirm reduction',onConfirm:()=>{d.headcount-=1;log(`${d.name} reduced one position and paid ${money(severance)} severance.`);persist({cash:cashAfter(severance)},'Department headcount reduced.');renderModal()}})}
function reviewPolicy(key,value,select){const d=management.departments[key],before=d.policy;if(value===before)return;review({title:`Change policy · ${d.name}`,summary:'Review the operating-policy change before it affects delegated work.',rows:[['Current policy',before],['New policy',value],['Headcount',`${d.headcount} active · ${pendingDepartment(key)} pending`]],confirmLabel:'Apply policy',onConfirm:()=>{d.policy=value;log(`${d.name} policy changed to ${value}.`);persist({},'Department policy updated.');renderModal()}});select.value=before}
function reviewDelegation(key,checked,input){const d=management.departments[key],before=d.enabled;input.checked=before;review({title:`${checked?'Delegate':'Take back'} routine work · ${d.name}`,summary:checked?'The department will handle routine work inside policy; exceptions still escalate to you.':'More routine work will require direct management attention.',rows:[['Current state',before?'Delegated':'Manual'],['After confirmation',checked?'Delegated':'Manual'],['Active people',String(d.headcount)],['Pending hires',String(pendingDepartment(key))]],confirmLabel:checked?'Delegate work':'Take back work',onConfirm:()=>{d.enabled=checked;const patch={delegation:{dispatch:management.departments.dispatch.enabled,production:management.departments.production.enabled,updates:management.departments.updates.enabled}};persist(patch,'Department responsibility updated.');renderModal()}})}
function reviewMaintenance(id){const a=management.fleet.find(x=>x.id===id);if(!a)return;if(a.status==='Maintenance')return review({title:`Return ${a.name} to service`,summary:'The asset passed inspection and can return to available inventory.',rows:[['Access model',a.accessModel],['Condition',`${Math.max(a.condition,94)}%`]],confirmLabel:'Return to service',onConfirm:()=>{a.status='Available';a.condition=Math.max(a.condition,94);persist({},`${a.name} returned to service.`);renderModal()}});const cost=6500;review({title:`Send ${a.name} to maintenance`,summary:'Preventive maintenance removes this asset from controlled capacity until you return it to service.',rows:[...financialRows(cost),['Access model',a.accessModel],['Current condition',`${a.condition}%`]],confirmLabel:'Approve maintenance',onConfirm:()=>{a.status='Maintenance';a.condition=Math.min(100,a.condition+5);persist({cash:cashAfter(cost)},`${a.name} moved to maintenance.`);renderModal()}})}
function reviewProcurement(id){const item=CAPACITY_CATALOG.find(x=>x.id===id);if(!item)return;if(cashAfter(item.upfront)<0)return toast('Not enough cash for this commitment.');const totals=capacityTotals(item.category);review({title:item.label,summary:`This creates ${item.accessModel.toLowerCase()} ${item.category.toLowerCase()} capacity after the procurement lead time.`,rows:[...financialRows(item.upfront,0,item.monthly,item.leadHours),['Controlled now',`${totals.onHand} ${item.unitLabel}`],['Partner accessible',`${totals.partner} ${item.unitLabel}`],['Controlled after arrival',`${totals.onHand+item.units} ${item.unitLabel}`],['Access model',item.accessModel]],warning:item.accessModel==='Owned'?'Ownership increases control and maintenance exposure.':item.accessModel==='Leased'?'Lease payments continue as a monthly fixed commitment.':'Contracted capacity is committed inventory for the scenario.',confirmLabel:'Approve procurement',onConfirm:()=>{management.capacityPipeline.push({id:uid('CAPREQ'),catalogId:item.id,label:item.label,upfront:item.upfront,readyAt:gameHour()+item.leadHours,asset:{kind:item.kind,category:item.category,accessModel:item.accessModel,units:item.units,unitLabel:item.unitLabel,name:item.label,base:item.base,capacity:item.capacity,monthlyCost:item.monthly,assignedDriver:item.accessModel==='Contracted'?'Partner network':''}});log(`${item.label} approved; availability expected H+${Math.round(gameHour()+item.leadHours)}.`);persist({cash:cashAfter(item.upfront)},'Capacity procurement approved.');renderModal()}})}
function callCarrier(id){const c=management.carriers.find(x=>x.id===id);if(!c)return;c.relationship=clamp(c.relationship+2,0,100);const response=['spot capacity reconfirmed','protected capacity offered','forecast requested before holding capacity','recovery capacity offered at a premium'][Math.floor(Math.random()*4)];log(`${c.contact} at ${c.name}: ${response}.`);persist({},`${c.name}: ${response}.`);renderModal()}
function reviewCarrierContract(id){const c=management.carriers.find(x=>x.id===id);if(!c)return;const preferred=Object.entries(c.access||{}).sort((a,b)=>b[1]-a[1])[0];if(!preferred)return toast('No partner capacity visible.');const [category,available]=preferred,units=Math.max(1,Math.ceil(available*.25)),rate=Math.round(28000*c.rate),unitLabel=category==='Ocean'?'FEU':category==='Air'?'pallets':'trucks',kind=category==='Ocean'?'Contracted vessel slot':category==='Air'?'Contracted air block':'Contracted truck';if(cashAfter(rate)<0)return toast('Not enough cash for the partner block.');review({title:`Contract capacity · ${c.name}`,summary:'Convert part of visible partner access into committed capacity you control.',rows:[...financialRows(rate,0,0,18),['Partner access now',`${available} ${unitLabel}`],['Contracting now',`${units} ${unitLabel}`],['Partner access after',`${Math.max(0,available-units)} ${unitLabel}`]],warning:'Partner access is not guaranteed until confirmed. This contract makes the selected block committed.',confirmLabel:'Confirm capacity contract',onConfirm:()=>{c.access[category]=Math.max(0,available-units);c.relationship=clamp(c.relationship+4,0,100);management.capacityPipeline.push({id:uid('CAPREQ'),label:`${c.name} ${category} block`,upfront:rate,readyAt:gameHour()+18,asset:{kind,category,accessModel:'Contracted',units,unitLabel,name:`${c.name} ${category} block`,base:c.markets,capacity:`${units} ${unitLabel}`,monthlyCost:0,assignedDriver:c.name}});persist({cash:cashAfter(rate)},`Capacity contract confirmed with ${c.name}.`);renderModal()}})}
function reviewDriverHire(id){const c=management.candidates.find(x=>x.id===id);if(!c)return;const fee=Math.round(c.salary*AGENCY_RATE),onboarding=3000,upfront=fee+onboarding;if(cashAfter(upfront)<0)return toast('Not enough cash for the agency fee and onboarding.');review({title:`Hire ${c.name}`,summary:'The staffing agency has presented this driver candidate. Approval starts background checks, onboarding, and notice-period lead time.',rows:[...financialRows(upfront,annualPayroll()+c.salary,0,c.leadHours),['Salary',money(c.salary)],['Agency fee',`${money(fee)} · 20%`],['Reliability',`${c.reliability}%`],['Region',c.region]],warning:'The driver is not dispatchable until the start time is reached.',confirmLabel:'Approve driver hire',onConfirm:()=>{management.staffingPipeline.push({id:uid('REQ'),kind:'driver',candidateId:c.id,name:c.name,region:c.region,reliability:c.reliability,salary:c.salary,upfront,readyAt:gameHour()+c.leadHours});persist({cash:cashAfter(upfront)},`${c.name} entered onboarding.`);renderModal()}})}
function reviewLoadOffer(id){const d=management.drivers.find(x=>x.id===id);if(!d||d.status!=='Available')return;const chance=clamp((d.reliability+d.morale)/200,.55,.96);review({title:`Offer priority load · ${d.name}`,summary:'Review the driver assignment before contacting them.',rows:[['Available hours',`${d.hours}h`],['Reliability',`${d.reliability}%`],['Morale',String(d.morale)],['Estimated acceptance',pct(chance)],['Hours after accepted',`${Math.max(0,d.hours-4)}h`]],confirmLabel:'Send load offer',onConfirm:()=>{const accepted=Math.random()<chance;if(accepted){d.status='Assigned';d.hours=Math.max(0,d.hours-4);persist({},`${d.name} accepted the priority load.`);setTimeout(()=>{d.status='Available';scheduleRefresh()},1200)}else{d.morale=clamp(d.morale-1,0,100);persist({},`${d.name} declined the timing.`)}renderModal()}})}
function reviewLaneBooking(id){const op=OPPORTUNITIES.find(x=>x.id===id),select=dialog.querySelector(`[data-carrier-for="${CSS.escape(id)}"]`),carrier=management.carriers.find(x=>x.id===select?.value);if(!op||!carrier)return toast('Choose a compatible carrier.');if(cashAfter(op.buy)<0)return toast('Not enough cash to book this lane.');review({title:`Book ${op.id} · ${hub(op.from).name} → ${hub(op.to).name}`,summary:'This is a commercial capacity and service commitment. Review the cash exposure and expected spread.',rows:[...financialRows(op.buy,0,0,op.hours),['Carrier',carrier.name],['Revenue if delivered',money(op.value)],['Gross spread before overhead',money(op.value-op.buy)],['Risk',op.risk]],warning:'Revenue is posted only when the simulated service completes.',confirmLabel:'Confirm lane booking',onConfirm:()=>{management.activeGlobal.push({...clone(op),carrierId:carrier.id,carrierName:carrier.name,startAt:gameHour(),finishAt:gameHour()+op.hours,status:'Moving'});carrier.relationship=clamp(carrier.relationship+3,0,100);persist({cash:cashAfter(op.buy)},`${op.id} is moving globally.`);renderModal()}})}

function wireModal(){dialog.querySelectorAll('[data-dept]').forEach(input=>input.onchange=()=>reviewDelegation(input.dataset.dept,input.checked,input));dialog.querySelectorAll('[data-request-hire]').forEach(b=>b.onclick=()=>requestDepartmentHire(b.dataset.requestHire));dialog.querySelectorAll('[data-reduce]').forEach(b=>b.onclick=()=>reduceDepartment(b.dataset.reduce));dialog.querySelectorAll('[data-policy]').forEach(s=>{const d=management.departments[s.dataset.policy];s.value=d.policy;s.onchange=()=>reviewPolicy(s.dataset.policy,s.value,s)});dialog.querySelectorAll('[data-maintain]').forEach(b=>b.onclick=()=>reviewMaintenance(b.dataset.maintain));dialog.querySelectorAll('[data-procure]').forEach(b=>b.onclick=()=>reviewProcurement(b.dataset.procure));dialog.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>callCarrier(b.dataset.call));dialog.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>reviewCarrierContract(b.dataset.contract));dialog.querySelectorAll('[data-offer]').forEach(b=>b.onclick=()=>reviewLoadOffer(b.dataset.offer));dialog.querySelectorAll('[data-hire-driver]').forEach(b=>b.onclick=()=>reviewDriverHire(b.dataset.hireDriver));dialog.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>reviewLaneBooking(b.dataset.book))}
function settleContracts(){const game=readGame(),now=Number(game.totalHours||8),ready=management.activeGlobal.filter(x=>x.status==='Moving'&&now>=x.finishAt);if(!ready.length)return;let cash=Number(game.cash||0),trust=Number(game.trust||82);for(const item of ready){cash+=item.value;trust=clamp(trust+1,0,100);management.completedGlobal.unshift({...item,status:'Delivered',deliveredAt:now});log(`${item.id} delivered ${hub(item.from).name} → ${hub(item.to).name}.`)}management.activeGlobal=management.activeGlobal.filter(x=>!ready.some(done=>done.id===x.id));persist({cash,trust},`${ready.length} global contract${ready.length===1?'':'s'} delivered.`)}
function installRoleStrip(){if($('#game-role-strip'))return;const briefing=$('.briefing-strip');if(!briefing)return;briefing.insertAdjacentHTML('afterend',`<section id="game-role-strip" class="game-role-strip"><div><p class="eyebrow">YOUR ROLE</p><strong>General Manager & Lead Dispatcher</strong><span>People, equipment, leases, and partner capacity all carry cost and lead time. Review before you commit.</span></div><button data-open-control="departments">Manage the company</button></section>`);$('#game-role-strip button').onclick=()=>openControl('departments')}
function wireEntryPoints(){const team=$('#open-team');if(team){team.textContent='Manage departments';team.onclick=()=>openControl('departments')}const automation=$('.automation-state');if(automation){automation.setAttribute('role','button');automation.tabIndex=0;automation.onclick=e=>{if(!e.target.closest('.game-info-button'))openControl('departments')};automation.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openControl('departments')}}}}
function decorateGlossary(){const targets=[...document.querySelectorAll('button,h2,h3,.automation-state,.map-help,.panel-help,.upgrade-card p')];for(const target of targets){const text=target.textContent.toLowerCase();for(const term of Object.keys(GLOSSARY)){if(!text.includes(term))continue;const existing=target.tagName==='BUTTON'?target.nextElementSibling?.matches?.(`.game-info-button[data-game-info="${CSS.escape(term)}"]`):target.querySelector?.(`.game-info-button[data-game-info="${CSS.escape(term)}"]`);if(existing)continue;const info=document.createElement('button');info.type='button';info.className='game-info-button';info.dataset.gameInfo=term;info.setAttribute('aria-label',`Explain ${term}`);info.textContent='i';if(target.tagName==='BUTTON')target.insertAdjacentElement('afterend',info);else target.append(info)}}}
function showInfo(term){const item=GLOSSARY[term];if(!item)return;let box=$('#game-info-dialog');if(!box){document.body.insertAdjacentHTML('beforeend',`<div id="game-info-dialog" class="game-info-dialog" hidden><div role="dialog" aria-modal="true"><button class="info-close" aria-label="Close">×</button><p class="eyebrow">GAME TERM</p><h2></h2><p class="info-copy"></p><button class="info-open-glossary">Open game glossary</button></div></div>`);box=$('#game-info-dialog');box.querySelector('.info-close').onclick=()=>box.hidden=true;box.querySelector('.info-open-glossary').onclick=()=>{box.hidden=true;openControl('glossary')};box.onclick=e=>{if(e.target===box)box.hidden=true}}box.querySelector('h2').textContent=item[0];box.querySelector('.info-copy').textContent=item[1];box.hidden=false}
document.addEventListener('click',e=>{const info=e.target.closest?.('.game-info-button');if(!info)return;e.preventDefault();e.stopPropagation();showInfo(info.dataset.gameInfo)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(reviewDialog&&!reviewDialog.hidden){reviewDialog.hidden=true;reviewAction=null}else if(!$('#game-info-dialog')?.hidden)$('#game-info-dialog').hidden=true;else if(dialog&&!dialog.hidden)closeControl()}});
window.addEventListener('atlas-main-game-map-ready',()=>setTimeout(globalizeMainMap,0));
window.addEventListener('atlas-game-loaded',event=>{if(syncing)return;management=mergeManagement(event.detail?.management||management);scheduleRefresh()});
window.addEventListener('atlas-game-changed',event=>{if(event.detail){event.detail.management=clone(management);if(window.__atlasGameState)window.__atlasGameState.management=clone(management);try{localStorage.setItem(GAME_KEY,JSON.stringify({...event.detail,management}))}catch{}}settleContracts();settlePipelines();scheduleRefresh()});
function initialize(){management=mergeManagement(readGame().management);ensureModal();ensureReview();installRoleStrip();renderDeck();wireEntryPoints();decorateGlossary();if(window.__atlasMainGameMap)globalizeMainMap();if(management.lastCostAt==null)management.lastCostAt=gameHour();settleContracts();settlePipelines()}
initialize();